-- hns-enrich and hns-recurring schedules (28.10.2026). Israel-time formats run twice (summer and winter UTC hours); the function
-- itself runs only at the right Israel hour (Friday 10:00, Thursday 12:00) and only once per week (keys in hns_recurring).
select cron.schedule('hns-enrich', '2-59/10 * * * *', $$ select net.http_post(url:='https://mgjmnvpnovkewvqevjmz.supabase.co/functions/v1/hns-enrich', body:='{"action":"tick"}'::jsonb, headers:=jsonb_build_object('content-type','application/json','x-cron-secret',(select v from public.app_secrets where k='CRON_SECRET')), timeout_milliseconds:=60000) $$);
select cron.schedule('hns-recurring-match', '4-59/15 * * * *', $$ select net.http_post(url:='https://mgjmnvpnovkewvqevjmz.supabase.co/functions/v1/hns-recurring', body:='{"action":"match"}'::jsonb, headers:=jsonb_build_object('content-type','application/json','x-cron-secret',(select v from public.app_secrets where k='CRON_SECRET')), timeout_milliseconds:=150000) $$);
select cron.schedule('hns-recurring-week', '1 7,8 * * 5', $$ select net.http_post(url:='https://mgjmnvpnovkewvqevjmz.supabase.co/functions/v1/hns-recurring', body:='{"action":"week"}'::jsonb, headers:=jsonb_build_object('content-type','application/json','x-cron-secret',(select v from public.app_secrets where k='CRON_SECRET')), timeout_milliseconds:=150000) $$);
select cron.schedule('hns-recurring-weekend', '1 9,10 * * 4', $$ select net.http_post(url:='https://mgjmnvpnovkewvqevjmz.supabase.co/functions/v1/hns-recurring', body:='{"action":"weekend"}'::jsonb, headers:=jsonb_build_object('content-type','application/json','x-cron-secret',(select v from public.app_secrets where k='CRON_SECRET')), timeout_milliseconds:=150000) $$);
select cron.schedule('hns-recurring-council', '25 * * * *', $$ select net.http_post(url:='https://mgjmnvpnovkewvqevjmz.supabase.co/functions/v1/hns-recurring', body:='{"action":"council"}'::jsonb, headers:=jsonb_build_object('content-type','application/json','x-cron-secret',(select v from public.app_secrets where k='CRON_SECRET')), timeout_milliseconds:=150000) $$);
